Func<dynamic, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Host is not Orc.Game.Cards.CardBase host) { return; }
    if (view.Player is not Orc.Game.Players.Player current) { return; }
    if (!object.ReferenceEquals(host.Owner, current)) { return; }

    if (host is not Orc.Game.Cards.UnitCard unit) { return; }
    if (!unit.TryGetData<Orc.Game.Cards.UnitStateData>(out var state) || state.IsDestroyed || state.Line is null)
    {
        return; // 未在场（未单位化/已死亡/无位置）：不获得
    }

    await unit.Modifiers.AddModifiersAsync(
        new Orc.Game.Cards.Modifier[]
        {
            new Orc.Game.Cards.AddModifier(Orc.Game.Cards.CardStatFields.Attack, 1, host),
            new Orc.Game.Cards.AddModifier(Orc.Game.Cards.CardStatFields.Defense, 1, host),
        },
        ct);
};
